// The batches example's transpile output: developer-owned generated source and
// the tests that drive it. This example exercises polymorphism over a shared
// record (Reference §6, §9; OQ35): a batch whose provenance is one of three
// kinds, spelled as a static union on a field rather than as subtypes, the
// cost of creating the batch and its origin together, and the probes that
// show what the direct subtype translation cannot say. Regenerated by
// `gradle generate`.
plugins {
    kotlin("jvm")
}

group = "velle"

repositories {
    mavenCentral()
}

dependencies {
    implementation(project(":compiler"))
    testImplementation(kotlin("test"))
    testImplementation(project(":stores:sqlite")) // the flows re-run over real storage
}

tasks.test {
    useJUnitPlatform()
}

tasks.register<JavaExec>("generate") {
    description = "Regenerate the Batches typed surface and executable specs from batches.velle"
    classpath = sourceSets["main"].runtimeClasspath
    mainClass.set("velle.GenerateKt")
    args("../batches.velle", "Batches")
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_21)
    }
}

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}
